Here's a practical pattern using the Cloud SQL Proxy and Centrifuge's Go client:

```go
import (
  "cloud.google.com/go/cloudsqlconn"
  centrifuge "github.com/centrifugal/centrifuge-go"
)

func NewPipeline(cfg Config) (*Pipeline, error) {
  dialer, err := cloudsqlconn.NewDialer(context.Background())
  if err != nil {
    return nil, err
  }
  dsn := dialer.FormatDSN(cfg.InstanceConnectionName)
  db, err := sql.Open("pgx", dsn)
  if err != nil {
    return nil, err
  }
  client := centrifuge.NewJsonClient(cfg.CentrifugeURL, centrifuge.Config{
    Token: cfg.CentrifugeToken,
  })
  return &Pipeline{db: db, client: client}, nil
}

func (p *Pipeline) StreamChanges(ctx context.Context) error {
  rows, err := p.db.QueryContext(ctx, "SELECT * FROM changes WHERE processed = false")
  if err != nil {
    return err
  }
  defer rows.Close()
  for rows.Next() {
    var change Change
    if err := rows.Scan(&change.ID, &change.Payload); err != nil {
      return err
    }
    if err := p.client.Publish(ctx, "changes", change.Payload); err != nil {
      return err
    }
  }
  return rows.Err()
}
```

